import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int K,
    int stride, int padding, int output_padding, int dilation,
    int groups, int C_in_per_group, int C_out_per_group)
{
    extern __shared__ float s_weight[];
    int block_id = blockIdx.x; // corresponds to (n, oc) pair
    int n = block_id / C_out;
    int oc = block_id % C_out;
    int g = oc / C_out_per_group;
    int oc_in_group = oc % C_out_per_group;
    int KKK = K * K * K;
    int weight_tile_size = C_in_per_group * KKK;
    // Cooperatively stage the weight slice for this (group, oc_in_group) into shared memory.
    // This slice is invariant across n and all spatial output positions handled by this block,
    // so caching it avoids redundant global memory traffic for every output element.
    for (int i = threadIdx.x; i < weight_tile_size; i += blockDim.x) {
        int ic = i / KKK;
        int rem = i % KKK;
        int kd = rem / (K * K);
        int rem2 = rem % (K * K);
        int kh = rem2 / K;
        int kw = rem2 % K;
        int ic_global = g * C_in_per_group + ic;
        long weight_idx = (((long)ic_global * C_out_per_group + oc_in_group) * K + kd) * K * K + (long)kh * K + kw;
        s_weight[i] = weight[weight_idx];
    }
    __syncthreads();
    long spatial_total = (long)D_out * H_out * W_out;
    const float* input_base = input + ((long)n * C_in) * D_in * H_in * W_in;
    bool has_bias = (bias != nullptr);
    float bias_val = has_bias ? bias[oc] : 0.0f;
    for (long sp = threadIdx.x; sp < spatial_total; sp += blockDim.x) {
        int ow = sp % W_out;
        long tmp = sp / W_out;
        int oh = tmp % H_out;
        int od = tmp / H_out;
        float sum = 0.0f;
        for (int kd = 0; kd < K; kd++) {
            int id_nom = od + padding - kd * dilation;
            if (id_nom % stride != 0) continue;
            int id = id_nom / stride;
            if (id < 0 || id >= D_in) continue;
            for (int kh = 0; kh < K; kh++) {
                int ih_nom = oh + padding - kh * dilation;
                if (ih_nom % stride != 0) continue;
                int ih = ih_nom / stride;
                if (ih < 0 || ih >= H_in) continue;
                for (int kw = 0; kw < K; kw++) {
                    int iw_nom = ow + padding - kw * dilation;
                    if (iw_nom % stride != 0) continue;
                    int iw = iw_nom / stride;
                    if (iw < 0 || iw >= W_in) continue;
                    int s_off = (kd * K + kh) * K + kw;
                    for (int ic = 0; ic < C_in_per_group; ic++) {
                        int ic_global = g * C_in_per_group + ic;
                        long input_idx = ((long)ic_global * D_in + id) * H_in * W_in + (long)ih * W_in + iw;
                        int s_idx = ic * KKK + s_off;
                        sum += input_base[input_idx] * s_weight[s_idx];
                    }
                }
            }
        }
        if (has_bias) {
            sum += bias_val;
        }
        long out_idx = (((long)n * C_out + oc) * D_out + od) * H_out * W_out + (long)oh * W_out + ow;
        output[out_idx] = sum;
    }
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int dilation,
    int groups)
{
    input = input.contiguous();
    weight = weight.contiguous();

    int N = input.size(0);
    int C_in = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);

    int K = weight.size(2);
    int C_out_per_group = weight.size(1);
    int C_out = C_out_per_group * groups;
    int C_in_per_group = C_in / groups;

    int D_out = (D_in - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    int H_out = (H_in - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    int W_out = (W_in - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;

    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());

    long total_blocks = (long)N * C_out;
    int threads = 256;
    size_t smem_bytes = (size_t)C_in_per_group * K * K * K * sizeof(float);
    const float* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }
    conv_transpose3d_kernel<<<total_blocks, threads, smem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, D_out, H_out, W_out,
        K,
        stride, padding, output_padding, dilation,
        groups, C_in_per_group, C_out_per_group
    );

    return output;
}
"""

conv_transpose3d_cpp_source = r"""
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int dilation,
    int groups);
"""

conv_transpose3d_module = load_inline(
    name="conv_transpose3d_module",
    cpp_sources=conv_transpose3d_cpp_source,
    cuda_sources=conv_transpose3d_source,
    functions=["conv_transpose3d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a transposed 3D convolution using a custom CUDA kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0,
                 output_padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()

        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.dilation = dilation
        self.groups = groups
        self.use_bias = bias

        # Weight layout matches nn.ConvTranspose3d: (in_channels, out_channels/groups, kD, kH, kW)
        self.weight = nn.Parameter(
            torch.empty(in_channels, out_channels // groups, kernel_size, kernel_size, kernel_size)
        )
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
            fan_in = out_channels // groups
            bound = 1 / (fan_in ** 0.5) if fan_in > 0 else 0
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous().cuda()
        weight = self.weight.contiguous().cuda()
        if self.use_bias:
            bias = self.bias.contiguous().cuda()
        else:
            bias = torch.tensor([], device=x.device, dtype=x.dtype)

        return conv_transpose3d_module.conv_transpose3d_cuda(
            x, weight, bias,
            self.stride, self.padding, self.output_padding, self.dilation, self.groups
        )


