    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int K,
    int stride, int padding, int output_padding, int dilation,
    int groups, int C_in_per_group, int C_out_per_group)
{
    long idx = blockIdx.x * (long)blockDim.x + threadIdx.x;
    long total = (long)N * C_out * D_out * H_out * W_out;
    if (idx >= total) return;

    int ow = idx % W_out;
    long tmp = idx / W_out;
    int oh = tmp % H_out;
    tmp /= H_out;
    int od = tmp % D_out;
    tmp /= D_out;
    int oc = tmp % C_out;
    int n = tmp / C_out;

    int g = oc / C_out_per_group;
    int oc_in_group = oc % C_out_per_group;

    float sum = 0.0f;

    for (int kd = 0; kd < K; kd++) {
        int id_nom = od + padding - kd * dilation;
        if (id_nom % stride != 0) continue;
        int id = id_nom / stride;
        if (id < 0 || id >= D_in) continue;

        for (int kh = 0; kh < K; kh++) {
            int ih_nom = oh + padding - kh * dilation;
            if (ih_nom % stride != 0) continue;
            int ih = ih_nom / stride;
            if (ih < 0 || ih >= H_in) continue;

            for (int kw = 0; kw < K; kw++) {
                int iw_nom = ow + padding - kw * dilation;
                if (iw_nom % stride != 0) continue;
                int iw = iw_nom / stride;
                if (iw < 0 || iw >= W_in) continue;

                const float* input_base = input + ((long)n * C_in) * D_in * H_in * W_in;
                const float* weight_base = weight;

                for (int ic = 0; ic < C_in_per_group; ic++) {
                    int ic_global = g * C_in_per_group + ic;
                    long input_idx = ((long)ic_global * D_in + id) * H_in * W_in + (long)ih * W_in + iw;
                    long weight_idx = (((long)ic_global * C_out_per_group + oc_in_group) * K + kd) * K * K + (long)kh * K + kw;
                    sum += input_base[input_idx] * weight_base[weight_idx];
                }
            }
        }
    }

    if (bias != nullptr) {
        sum += bias[oc];
    }

    output[idx] = sum;
}

torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int dilation,
    int groups)
{
    input = input.contiguous();
    weight = weight.contiguous();

    int N = input.size(0);
    int C_in = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);

    int K = weight.size(2);
    int C_out_per_group = weight.size(1);
    int C_out = C_out_per_group * groups;
    int C_in_per_group = C_in / groups;

    int D_out = (D_in - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    int H_out = (H_in - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;
    int W_out = (W_in - 1) * stride - 2 * padding + dilation * (K - 1) + output_padding + 1;

    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());

    long total = (long)N * C_out * D_out * H_out * W_out;
    int threads = 256;
    long blocks = (total + threads - 1) / threads;

    const float* bias_ptr = nullptr;
    if (bias.defined() && bias.numel() > 0) {
        bias = bias.contiguous();
        bias_ptr = bias.data_ptr<float>();
    }

    conv_transpose3d_kernel<<<blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, D_out, H_out, W_out,
        K,
        stride, padding, output_padding, dilation,
        groups, C_in_per_group, C_out_per_group
    );

    return output;
}
